after:
```swift
struct Ticket {
    let label: String
    func message() -> String {
        "Ticket: \(label)"
    }
}
struct Holder {
    let ticket: Ticket?
}
let holder = Holder(ticket: Ticket(label: "Balcony"))
let text = holder.ticket?.message() ?? "No ticket"
print(text)
```
The output is `Ticket: Balcony`. The ticket exists, so its message method runs.
